  it.each(["", "   ", "0", "0.00", "-5", "0x10", "1e3", "1E3", "+5", "1.234", "1.2.3", "12a", "abc", ".5", "500.", "1,000"])(
    "rejects amount %j",
    (amount) => {
      const { errors, value } = base(amount);
      expect(typeof errors.amount).toBe("string");
      expect(errors.amount).not.toBe("");
      expect(value).toBeNull();
    },
  );
});

