// Versioned localStorage persistence for the mutable demo state.
// Every load path is defensive: any problem yields a "recovered" result (or "empty"), never an exception.
// Saved data is validated in full before use; anything malformed falls back to the seed data.

import type { Bill, BillPayment, CashAccount, Invoice, Payment } from "../types";
import { isValidIsoDate } from "../utils/bills";

export const STORAGE_KEY = "ps01-back-office:state";
export const SCHEMA_VERSION = 1;

/** The persistable subset of app state. resetCount is session-only and is not stored. */
export interface PersistedData {
  bills: Bill[];
  billPayments: BillPayment[];
  cashAccounts: CashAccount[];
  invoices: Invoice[];
  payments: Payment[];
}

export type LoadResult =
  | { status: "loaded"; data: PersistedData }
  | { status: "empty" }
  | { status: "recovered"; reason: string };

const BILL_STATUSES = ["upcoming", "paid", "overdue"] as const;
const RECURRENCES = ["one-time", "monthly", "quarterly", "yearly"] as const;
const INVOICE_STATUSES = ["draft", "sent", "paid", "overdue"] as const;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isFiniteAmount(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function isNonNegativeAmount(value: unknown): value is number {
  return isFiniteAmount(value) && value >= 0;
}

function isIsoDate(value: unknown): value is string {
  return typeof value === "string" && isValidIsoDate(value);
}

function isOneOf<T extends string>(value: unknown, allowed: readonly T[]): value is T {
  return typeof value === "string" && (allowed as readonly string[]).includes(value);
}

/** An optional field is absent (undefined) or passes the given check. */
function isOptional(record: Record<string, unknown>, key: string, check: (value: unknown) => boolean): boolean {
  return record[key] === undefined || check(record[key]);
}

function isBill(value: unknown): value is Bill {
  if (!isPlainObject(value)) return false;
  return (
    isNonEmptyString(value.id) &&
    typeof value.name === "string" &&
    typeof value.category === "string" &&
    isNonNegativeAmount(value.amountINR) &&
    isIsoDate(value.dueDate) &&
    isOneOf(value.status, BILL_STATUSES) &&
    isOneOf(value.recurrence, RECURRENCES) &&
    isOptional(value, "anchorDate", isIsoDate)
  );
}

function isBillPayment(value: unknown): value is BillPayment {
  if (!isPlainObject(value)) return false;
  return (
    isNonEmptyString(value.id) &&
    isNonEmptyString(value.billId) &&
    isNonEmptyString(value.accountId) &&
    isNonNegativeAmount(value.amountINR) &&
    isIsoDate(value.paidDate) &&
    isIsoDate(value.occurrenceDueDate)
  );
}

function isCashAccount(value: unknown): value is CashAccount {
  if (!isPlainObject(value)) return false;
  return (
    isNonEmptyString(value.id) &&
    typeof value.label === "string" &&
    isFiniteAmount(value.balanceINR) &&
    isIsoDate(value.asOfDate)
  );
}

function isInvoice(value: unknown): value is Invoice {
  if (!isPlainObject(value)) return false;
  return (
    isNonEmptyString(value.id) &&
    typeof value.clientId === "string" &&
    typeof value.description === "string" &&
    isNonNegativeAmount(value.amountINR) &&
    isIsoDate(value.issueDate) &&
    isIsoDate(value.dueDate) &&
    isOneOf(value.status, INVOICE_STATUSES) &&
    isOptional(value, "paidDate", isIsoDate)
  );
}

function isPayment(value: unknown): value is Payment {
  if (!isPlainObject(value)) return false;
  return (
    isNonEmptyString(value.id) &&
    isNonEmptyString(value.invoiceId) &&
    isNonNegativeAmount(value.amountINR) &&
    isIsoDate(value.receivedDate)
  );
}

/** Returns shallow copies of the items if `value` is an array whose every item passes `guard`; otherwise null. */
function parseList<T>(value: unknown, guard: (item: unknown) => item is T): T[] | null {
  if (!Array.isArray(value)) return null;
  if (!value.every(guard)) return null;
  return value.map((item) => ({ ...item }));
}

function idsAreUnique(items: readonly { id: string }[]): boolean {
  return new Set(items.map((item) => item.id)).size === items.length;
}

/**
 * Full schema check of persisted data. Returns a new object with copied arrays, or null on ANY problem:
 * wrong shapes or types, invalid enums or dates, negative/non-finite amounts, duplicate ids,
 * or broken references (billPayment -> bill/account, payment -> invoice).
 */
export function validatePersistedData(value: unknown): PersistedData | null {
  if (!isPlainObject(value)) return null;

  const bills = parseList(value.bills, isBill);
  const billPayments = parseList(value.billPayments, isBillPayment);
  const cashAccounts = parseList(value.cashAccounts, isCashAccount);
  const invoices = parseList(value.invoices, isInvoice);
  const payments = parseList(value.payments, isPayment);
  if (!bills || !billPayments || !cashAccounts || !invoices || !payments) return null;

  if (!idsAreUnique(bills) || !idsAreUnique(billPayments) || !idsAreUnique(cashAccounts)) return null;
  if (!idsAreUnique(invoices) || !idsAreUnique(payments)) return null;

  const billIds = new Set(bills.map((bill) => bill.id));
  const accountIds = new Set(cashAccounts.map((account) => account.id));
  const invoiceIds = new Set(invoices.map((invoice) => invoice.id));

  if (!billPayments.every((payment) => billIds.has(payment.billId) && accountIds.has(payment.accountId))) return null;
  if (!payments.every((payment) => invoiceIds.has(payment.invoiceId))) return null;

  return { bills, billPayments, cashAccounts, invoices, payments };
}

function getStorage(): Storage | null {
  try {
    return typeof window !== "undefined" && window.localStorage ? window.localStorage : null;
  } catch {
    // Accessing localStorage can throw (e.g. disabled cookies or sandboxed iframes).
    return null;
  }
}

/** Reads and validates saved state. Never throws; any problem yields "recovered" (or "empty" when nothing is saved). */
export function loadPersistedData(storage: Storage | null | undefined = getStorage()): LoadResult {
  if (!storage) return { status: "empty" };

  let raw: string | null;
  try {
    raw = storage.getItem(STORAGE_KEY);
  } catch {
    return { status: "recovered", reason: "Storage is unavailable; using demo data." };
  }
  if (raw === null) return { status: "empty" };

  let envelope: unknown;
  try {
    envelope = JSON.parse(raw);
  } catch {
    return { status: "recovered", reason: "Saved data was unreadable; using demo data." };
  }
  if (!isPlainObject(envelope)) {
    return { status: "recovered", reason: "Saved data was unreadable; using demo data." };
  }
  if (envelope.version !== SCHEMA_VERSION) {
    return { status: "recovered", reason: "Saved data is from an incompatible version; using demo data." };
  }

  const data = validatePersistedData(envelope.data);
  if (!data) {
    return { status: "recovered", reason: "Saved data failed validation; using demo data." };
  }
  return { status: "loaded", data };
}

/** Writes the persistable state. Returns true on success, false on any failure. Never throws. */
export function savePersistedData(data: PersistedData, storage: Storage | null | undefined = getStorage()): boolean {
  if (!storage) return false;
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify({ version: SCHEMA_VERSION, data }));
    return true;
  } catch (error) {
    console.warn("Could not save demo data to localStorage.", error);
    return false;
  }
}

/** Removes the saved state. Returns true on success, false on any failure. Never throws. */
export function clearPersistedData(storage: Storage | null | undefined = getStorage()): boolean {
  if (!storage) return false;
  try {
    storage.removeItem(STORAGE_KEY);
    return true;
  } catch (error) {
    console.warn("Could not clear saved demo data from localStorage.", error);
    return false;
  }
}

import { describe, expect, it, vi } from "vitest";
import { bills as seedBills, cashAccounts as seedCashAccounts, invoices as seedInvoices, payments as seedPayments } from "../data/seed";
import type { BillPayment } from "../types";
import { appStateReducer, type AppState } from "./AppState";
import {
  STORAGE_KEY,
  clearPersistedData,
  loadPersistedData,
  savePersistedData,
  validatePersistedData,
  type PersistedData,
} from "./persistence";

const INCOMPATIBLE = "Saved data is from an incompatible version; using demo data.";
const UNREADABLE = "Saved data was unreadable; using demo data.";
const INVALID = "Saved data failed validation; using demo data.";

/** In-memory Storage stand-in; only the three methods the persistence module uses are implemented. */
function fakeStorage(): Storage {
  const map = new Map<string, string>();
  return {
    getItem: (key: string) => map.get(key) ?? null,
    setItem: (key: string, value: string) => {
      map.set(key, value);
    },
    removeItem: (key: string) => {
      map.delete(key);
    },
  } as unknown as Storage;
}

function seedData(): PersistedData {
  return structuredClone({
    bills: seedBills,
    billPayments: [] as BillPayment[],
    cashAccounts: seedCashAccounts,
    invoices: seedInvoices,
    payments: seedPayments,
  });
}

/** Writes raw text straight into storage, bypassing save, to simulate corrupt or foreign data. */
function writeRaw(storage: Storage, text: string): void {
  storage.setItem(STORAGE_KEY, text);
}

function writeEnvelope(storage: Storage, data: unknown, version: unknown = 1): void {
  writeRaw(storage, JSON.stringify({ version, data }));
}

describe("persistence round trip", () => {
  it("loads back seed-shaped data equal to what was saved", () => {
    const storage = fakeStorage();
    const data = seedData();

    expect(savePersistedData(data, storage)).toBe(true);
    const result = loadPersistedData(storage);

    expect(result.status).toBe("loaded");
    if (result.status === "loaded") {
      expect(result.data).toEqual(data);
    }
  });

  it("returns empty when nothing has been saved yet", () => {
    expect(loadPersistedData(fakeStorage())).toEqual({ status: "empty" });
  });

  it("clearPersistedData removes the key so loading returns empty", () => {
    const storage = fakeStorage();
    savePersistedData(seedData(), storage);

    expect(clearPersistedData(storage)).toBe(true);
    expect(loadPersistedData(storage)).toEqual({ status: "empty" });
  });
});

describe("storage availability", () => {
  it("returns empty when there is no storage at all", () => {
    expect(loadPersistedData(null)).toEqual({ status: "empty" });
    expect(savePersistedData(seedData(), null)).toBe(false);
    expect(clearPersistedData(null)).toBe(false);
  });

  it("recovers when reading storage throws", () => {
    const storage = {
      getItem: () => {
        throw new Error("SecurityError");
      },
      setItem: () => undefined,
      removeItem: () => undefined,
    } as unknown as Storage;

    expect(loadPersistedData(storage)).toEqual({
      status: "recovered",
      reason: "Storage is unavailable; using demo data.",
    });
  });

  it("returns false without throwing when writing storage throws", () => {
    vi.spyOn(console, "warn").mockImplementation(() => undefined);
    const storage = {
      getItem: () => null,
      setItem: () => {
        throw new Error("QuotaExceededError");
      },
      removeItem: () => undefined,
    } as unknown as Storage;

    expect(() => savePersistedData(seedData(), storage)).not.toThrow();
    expect(savePersistedData(seedData(), storage)).toBe(false);
  });
});

describe("loadPersistedData recovery", () => {
  it("recovers from corrupt JSON", () => {
    const storage = fakeStorage();
    writeRaw(storage, "{not json");

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: UNREADABLE });
  });

  it("recovers from an incompatible schema version", () => {
    const storage = fakeStorage();
    writeEnvelope(storage, seedData(), 99);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INCOMPATIBLE });
  });

  it("recovers when an array field is missing", () => {
    const storage = fakeStorage();
    const data: Partial<PersistedData> = seedData();
    delete data.payments;
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when a bill amount is a string", () => {
    const storage = fakeStorage();
    const data = seedData();
    (data.bills[0] as unknown as { amountINR: unknown }).amountINR = "100";
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when a bill date is an impossible calendar date", () => {
    const storage = fakeStorage();
    const data = seedData();
    data.bills[0] = { ...data.bills[0], dueDate: "2026-02-30" };
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when an invoice status is not a known value", () => {
    const storage = fakeStorage();
    const data = seedData();
    (data.invoices[0] as unknown as { status: string }).status = "weird";
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when an amount is negative", () => {
    const storage = fakeStorage();
    const data = seedData();
    data.bills[0] = { ...data.bills[0], amountINR: -5 };
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when two bills share an id", () => {
    const storage = fakeStorage();
    const data = seedData();
    data.bills[1] = { ...data.bills[1], id: data.bills[0].id };
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when a bill payment references a missing bill", () => {
    const storage = fakeStorage();
    const data = seedData();
    data.billPayments = [
      {
        id: "BP-1",
        billId: "B-MISSING",
        accountId: seedCashAccounts[0].id,
        amountINR: 1000,
        paidDate: "2025-06-15",
        occurrenceDueDate: "2025-06-20",
      },
    ];
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when a bill payment references a missing cash account", () => {
    const storage = fakeStorage();
    const data = seedData();
    data.billPayments = [
      {
        id: "BP-1",
        billId: seedBills[0].id,
        accountId: "CA-MISSING",
        amountINR: 1000,
        paidDate: "2025-06-15",
        occurrenceDueDate: "2025-06-20",
      },
    ];
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("recovers when a payment references a missing invoice", () => {
    const storage = fakeStorage();
    const data = seedData();
    data.payments = [{ id: "P-X", invoiceId: "INV-MISSING", amountINR: 1000, receivedDate: "2025-06-15" }];
    writeEnvelope(storage, data);

    expect(loadPersistedData(storage)).toEqual({ status: "recovered", reason: INVALID });
  });

  it("accepts two legitimately separate bills that share a name and amount", () => {
    const storage = fakeStorage();
    const data = seedData();
    data.bills.push({ ...data.bills[0], id: "B-DUP-LOOKALIKE" });
    writeEnvelope(storage, data);

    const result = loadPersistedData(storage);
    expect(result.status).toBe("loaded");
  });
});

describe("validatePersistedData", () => {
  it("returns null for a non-object value", () => {
    expect(validatePersistedData(null)).toBeNull();
    expect(validatePersistedData([])).toBeNull();
    expect(validatePersistedData("text")).toBeNull();
  });

  it("returns copies of the arrays, not the input references", () => {
    const input = seedData();
    const validated = validatePersistedData(input);

    expect(validated).not.toBeNull();
    expect(validated?.bills).not.toBe(input.bills);
    expect(validated?.bills[0]).not.toBe(input.bills[0]);
  });
});

describe("appStateReducer reset with persisted billPayments", () => {
  it("clears billPayments and restores the seed bills and cash accounts", () => {
    const state: AppState = {
